From 8aa4b82508b622b53cc606f3b7920e0652e27da9 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 08:42:56 +0100
Subject: [PATCH] devicenotifications: Delay the notification for USB audio
 devices

The sound played as soon as the device appeared, before the new output
was ready, so it started on the previous output and was cut off there.
Now it waits two seconds for audio devices, then plays on the new one.

BUG: 517925
---
 devicenotifications/devicenotifications.cpp | 28 ++++++++++++++++++++-
 devicenotifications/devicenotifications.h   |  1 +
 2 files changed, 28 insertions(+), 1 deletion(-)

diff --git a/devicenotifications/devicenotifications.cpp b/devicenotifications/devicenotifications.cpp
index d562280311..8fb6d83524 100644
--- a/devicenotifications/devicenotifications.cpp
+++ b/devicenotifications/devicenotifications.cpp
@@ -11,6 +11,7 @@
 #include <KLocalizedString>
 #include <KPluginFactory>

+#include <algorithm>
 #include <chrono>

 #include <knotification.h>
@@ -210,6 +211,15 @@ QString UdevDevice::displayName() const
     return displayNameSegments.join(QLatin1Char(' '));
 }

+bool UdevDevice::hasAudioInterface() const
+{
+    // List of the device's interfaces as ":ccsspp:" (class, subclass, protocol), class 01 is audio.
+    const QStringList interfaces = deviceProperty("ID_USB_INTERFACES").split(QLatin1Char(':'), Qt::SkipEmptyParts);
+    return std::ranges::any_of(interfaces, [](const QString &interface) {
+        return interface.startsWith(QLatin1String("01"));
+    });
+}
+
 bool UdevDevice::isRemovable() const
 {
     // "removable" is a device that can be removed from the platform by the user.
@@ -606,7 +616,23 @@ void KdedDeviceNotifications::onDeviceAdded(const UdevDevice &device)
     m_usbDeviceAddedNotification->setIconName(QStringLiteral("drive-removable-media-usb"));
     m_usbDeviceAddedNotification->setTitle(i18nc("@title:notifications", "USB Device Detected"));
     m_usbDeviceAddedNotification->setText(text);
-    m_usbDeviceAddedNotification->sendEvent();
+    // Give the sound system time to switch to a new audio device, otherwise
+    // the notification sound starts playing on the previous output.
+    if (device.hasAudioInterface()) {
+        QTimer::singleShot(2s, this, [this, notification = m_usbDeviceAddedNotification] {
+            if (!notification) {
+                return;
+            }
+            // Closing a notification that wasn't sent yet doesn't delete it.
+            if (notification == m_usbDeviceAddedNotification) {
+                notification->sendEvent();
+            } else {
+                notification->deleteLater();
+            }
+        });
+    } else {
+        m_usbDeviceAddedNotification->sendEvent();
+    }

     m_deviceAddedTimer.start();
 }
diff --git a/devicenotifications/devicenotifications.h b/devicenotifications/devicenotifications.h
index c4fac9bd66..1777d707bd 100644
--- a/devicenotifications/devicenotifications.h
+++ b/devicenotifications/devicenotifications.h
@@ -45,6 +45,7 @@ public:
     QString vendor() const;
     QString displayName() const;

+    bool hasAudioInterface() const;
     bool isRemovable() const;

 private:
-- 
